    slug: "n8n-multi-channel-publish",
    title: "n8n 多平台内容一键分发流水线",
    summary: "一篇成稿自动适配公众号、小红书与视频口播提纲。",
    description:
      "独立开发者或内容团队用 n8n 串联写作 Agent：母稿完成后自动生成各平台裁剪版，写入草稿箱或发送审核群，降低重复排版成本。",
