      "锁文件片段不完整时不要推断未出现的传递依赖树；需要时请用户补充 `npm ls`／锁文件相关段。",
      "上面写的是 npm 公开的语义化版本说明，不是 npm 公布的「用 Agent 做升级评估可省 X 小时」类量化指标。",
