      "客户群／外部联系人场景权限与内部群不同；仅摘要级处理，且须符合企业授权与隐私政策。",
      "上面写的是企微开放文档公开的发送能力与限频说明，不是其公布的「用 Agent 做日汇总可省 X 小时」类量化指标。",
