      "硬约束：禁止在生产账号上让浏览器 Agent 随意点击；禁止越权登录与代为付款/下单；写操作须人确认；禁止保存生产 Cookie/密码到评测脚本或飞书。",
      "网络波动与验证码会导致结果不稳定，同一任务至少两轮；测评记录脱敏，避免把客户数据贴进公开频道。",
