      "作者自述：约 15 个工作日完成规划到 QA 交接量级的迁移 POC，约 50 工单/约 580 测试，并给出覆盖率与近 5000 美元 token 成本等自述口径（文中陈述，非我方实测，不可外推为普遍工期或成本）。",
      "团队可把缠绕换栈收成「模块级可审 PR + 回滚说明 + 灰度」；是否合入、是否打开生产开关仍由人依据 CI 与值班清单决定，禁止 Agent 一次切全生产。",
