    approach: `vitraag.com（Vaibhav Bhandari）文《AI-Assisted Grading with Canvas API and Claude》记述：为 Peralta/Merritt College 的 CIS-55（Hacker Techniques & Exploits）课程搭批改流水线——Discover→Download→AI Grade→Human Review→Upload；用个人 Canvas Access Token 经 REST 拉 online_upload 提交与附件，量规以 YAML 为真源，Claude 按维度返回 scores/total/comment/flag/confidence 的结构化 JSON，再落到待审 CSV（含 skip 列、标记置顶），确认「Post N grades to Canvas? [y/N]」后才回写 SpeedGrader。作者自述某次 Lab 5 约 22 份提交中有 13 份被 flag（多为疑似 AI 生成或证据薄弱），并设提交最低分地板等课程政策；扫描型 PDF 走视觉回退。公开文未给出与教师人工分的一致性、申诉率或全班省时小时数等可外推量化。

国内落地收成「Canvas/同类 LMS 只读拉取提交+量规 → Agent 按维度建议分与评语草稿 → 飞书/企微待审表（强制抽检比例）→ 教师抽检修改并确认后才回写正式成绩」。硬约束：建议分与评语须人审后再入正式成绩册，禁止未经教师确认定稿；学生作业、评语与成绩仅存校内可控目录，对外摘要须脱敏学号/姓名等标识，禁止未审批外发；疑似抄袭/AI 代写只标「需人工复核」，不做自动处分或通报。`,
