    approach: `管道爆裂、暴雨进屋或台风损屋之后，投保人最缺的不是情绪宣泄，而是可交接的材料夹：保单在哪、拍了什么、跟谁说过什么。本地化做法是让 Agent 管「己方卷宗」，不代替保险公司定损。

可参考金融监管部门在公开吹风中强调的巨灾/灾害保险保障与行业加快理赔、尽赔快赔预赔等方向，把家财险理赔拆成可跟踪步骤。Agent 输出：材料目录、损失清单模板、查勘前自检、沟通日志、争议时需要保留的证据清单。禁止伪造发票或夸大损失，禁止承诺具体赔付额。`,
