    approach: `独立开发者常在「能用这个库吗」卡住：README 写 MIT，传递依赖却冒出 GPL/AGPL 字样。本地化做法是先做 SPDX 级自检，再决定是否升级法务投入。

以 SPDX License List 的公开发布为标识权威来源之一（版本发布会新增/修订许可证与例外条目）。Agent 输出：依赖许可清单、与 outbound 许可的「看起来可能不兼容 / 信息不足 / 常见上可组合」三档（仅启发式）、需要保留的版权与 NOTICE 提醒、给法务的复核问题。明确声明：兼容性因司法辖区与分发方式而异，模型输出不是法律意见。`,
