    summary: "按 integrity 最强哈希选用、匹配失败网络错误与 crossorigin/CORS 要求，生成 CDN 脚本样式 SRI 失败分诊表；不代改线上标签。",
    description:
      "面向独立开发者与内容站点：把「CDN 脚本突然不执行」写成 SRI/CORS 对照清单，区别于混合内容或纯缓存刷新。",
